import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { Router, provideRouter } from '@angular/router';
import { VehicleForm } from './vehicle-form';

describe('VehicleForm', () => {
  let fixture: ComponentFixture<VehicleForm>;
  let element: HTMLElement;
  let http: HttpTestingController;

  beforeEach(async () => {
    TestBed.configureTestingModule({
      providers: [provideHttpClient(), provideHttpClientTesting(), provideRouter([])],
    });
    fixture = TestBed.createComponent(VehicleForm);
    element = fixture.nativeElement;
    http = TestBed.inject(HttpTestingController);
    await fixture.whenStable();
  });

  afterEach(() => http.verify());

  function fill(type: string, index: number, value: string): void {
    const input = element.querySelectorAll<HTMLInputElement>(`input[type="${type}"]`)[index];
    input.value = value;
    input.dispatchEvent(new Event('input'));
  }

  function select(value: string): void {
    const select = element.querySelector('select')!;
    select.value = value;
    select.dispatchEvent(new Event('input'));
  }

  function fillValidVehicle(): void {
    fill('text', 0, 'WVWZZZ1KZAW000001');
    fill('text', 1, 'Volkswagen');
    fill('text', 2, 'Golf');
    fill('number', 0, '2025');
    select('PETROL');
  }

  async function submit(): Promise<void> {
    element.querySelector('form')!.dispatchEvent(new Event('submit'));
    await fixture.whenStable();
  }

  function errors(): string[] {
    return Array.from(element.querySelectorAll('.error'), (error) => error.textContent!.trim());
  }

  it('shows required errors and sends nothing when the form is empty', async () => {
    await submit();

    http.expectNone('/api/vehicles');
    expect(errors()).toEqual([
      'VIN is required',
      'Make is required',
      'Model is required',
      'Production year is required',
      'Fuel type is required',
    ]);
  });

  it('leaves format and range rules to the backend', async () => {
    fillValidVehicle();
    fill('text', 0, 'TOO-SHORT');
    fill('number', 0, '1800');

    await submit();

    const request = http.expectOne({ method: 'POST', url: '/api/vehicles' });
    expect(request.request.body.vin).toBe('TOO-SHORT');
    expect(request.request.body.productionYear).toBe(1800);
    request.flush(
      {
        title: 'Bad Request',
        status: 400,
        detail: 'Validation failed',
        errors: [
          { field: 'productionYear', message: 'must be between 1990 and next year' },
          {
            field: 'vin',
            message: 'must be 17 characters: digits and capital letters except I, O, Q',
          },
        ],
      },
      { status: 400, statusText: 'Bad Request' },
    );

    await vi.waitFor(() =>
      expect(errors()).toEqual([
        'must be 17 characters: digits and capital letters except I, O, Q',
        'must be between 1990 and next year',
      ]),
    );
  });

  it('creates the vehicle and navigates to its details', async () => {
    const navigate = vi.spyOn(TestBed.inject(Router), 'navigate').mockResolvedValue(true);
    fillValidVehicle();
    fill('date', 0, '2026-12-15');

    await submit();
    const request = http.expectOne({ method: 'POST', url: '/api/vehicles' });
    expect(request.request.body).toEqual({
      vin: 'WVWZZZ1KZAW000001',
      make: 'Volkswagen',
      model: 'Golf',
      productionYear: 2025,
      fuelType: 'PETROL',
      plannedHandoverDate: '2026-12-15',
    });
    request.flush({ id: 7, ...request.request.body });

    await vi.waitFor(() => expect(navigate).toHaveBeenCalledWith(['/vehicles', 7]));
  });

  it('loads the vehicle in edit mode and updates it', async () => {
    const navigate = vi.spyOn(TestBed.inject(Router), 'navigate').mockResolvedValue(true);
    const vehicle = {
      id: 3,
      vin: 'TMBJJ7NE8L0000003',
      make: 'Skoda',
      model: 'Octavia',
      productionYear: 2026,
      fuelType: 'HYBRID',
      plannedHandoverDate: null,
    };
    fixture.componentRef.setInput('id', '3');
    fixture.detectChanges();
    http.expectOne({ method: 'GET', url: '/api/vehicles/3' }).flush(vehicle);
    await fixture.whenStable();
    fill('text', 2, 'Superb');

    await submit();
    const request = http.expectOne({ method: 'PUT', url: '/api/vehicles/3' });
    expect(request.request.body).toEqual({
      vin: 'TMBJJ7NE8L0000003',
      make: 'Skoda',
      model: 'Superb',
      productionYear: 2026,
      fuelType: 'HYBRID',
      plannedHandoverDate: null,
    });
    request.flush({ ...vehicle, model: 'Superb' });

    await vi.waitFor(() => expect(navigate).toHaveBeenCalledWith(['/vehicles', 3]));
  });

  it('shows a dedicated message when the vehicle to edit does not exist', async () => {
    fixture.componentRef.setInput('id', '99');
    fixture.detectChanges();
    http
      .expectOne({ method: 'GET', url: '/api/vehicles/99' })
      .flush(
        { title: 'Not Found', status: 404, detail: 'Vehicle with id 99 not found' },
        { status: 404, statusText: 'Not Found' },
      );

    await vi.waitFor(() => expect(errors()).toEqual(['Vehicle not found']));
  });

  it('shows the ProblemDetail detail when loading the vehicle fails', async () => {
    fixture.componentRef.setInput('id', '3');
    fixture.detectChanges();
    http
      .expectOne({ method: 'GET', url: '/api/vehicles/3' })
      .flush(
        { title: 'Service Unavailable', status: 503, detail: 'Database is unavailable' },
        { status: 503, statusText: 'Service Unavailable' },
      );

    await vi.waitFor(() => expect(errors()).toEqual(['Database is unavailable']));
  });

  it('shows object-level errors returned by the backend above the form', async () => {
    fillValidVehicle();

    await submit();
    http.expectOne({ method: 'POST', url: '/api/vehicles' }).flush(
      {
        title: 'Bad Request',
        status: 400,
        detail: 'Validation failed',
        errors: [{ field: null, message: 'request body must be valid JSON' }],
      },
      { status: 400, statusText: 'Bad Request' },
    );

    await vi.waitFor(() => expect(errors()).toEqual(['request body must be valid JSON']));
  });

  it('shows field errors returned by the backend as ProblemDetail', async () => {
    fillValidVehicle();

    await submit();
    http.expectOne({ method: 'POST', url: '/api/vehicles' }).flush(
      {
        title: 'Bad Request',
        status: 400,
        detail: 'Validation failed',
        errors: [{ field: 'productionYear', message: 'must be between 1990 and next year' }],
      },
      { status: 400, statusText: 'Bad Request' },
    );

    await vi.waitFor(() => expect(errors()).toEqual(['must be between 1990 and next year']));
  });

  it('shows the ProblemDetail detail when the backend reports a conflict', async () => {
    fillValidVehicle();

    await submit();
    http.expectOne({ method: 'POST', url: '/api/vehicles' }).flush(
      {
        title: 'Conflict',
        status: 409,
        detail: 'Vehicle with VIN WVWZZZ1KZAW000001 already exists',
      },
      { status: 409, statusText: 'Conflict' },
    );

    await vi.waitFor(() =>
      expect(errors()).toEqual(['Vehicle with VIN WVWZZZ1KZAW000001 already exists']),
    );
  });
});
import { Component, computed, inject, input, linkedSignal } from '@angular/core';
import { FormField, FormRoot, form, required } from '@angular/forms/signals';
import { Router, RouterLink } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { loadErrorMessage, problemDetailToFormErrors } from '../shared/problem-detail';
import { optionalNumberAttribute } from '../shared/route-params';
import {
  FUEL_TYPES,
  FUEL_TYPE_LABELS,
  FuelType,
  Vehicle,
  VehicleApi,
  VehicleRequest,
} from './vehicle-api';

interface VehicleFormModel {
  vin: string;
  make: string;
  model: string;
  productionYear: number | null;
  fuelType: FuelType | '';
  plannedHandoverDate: string;
}

function toFormModel(vehicle: Vehicle | undefined): VehicleFormModel {
  return {
    vin: vehicle?.vin ?? '',
    make: vehicle?.make ?? '',
    model: vehicle?.model ?? '',
    productionYear: vehicle?.productionYear ?? null,
    fuelType: vehicle?.fuelType ?? '',
    plannedHandoverDate: vehicle?.plannedHandoverDate ?? '',
  };
}

function toRequest(model: VehicleFormModel): VehicleRequest {
  return {
    vin: model.vin,
    make: model.make,
    model: model.model,
    productionYear: model.productionYear!,
    fuelType: model.fuelType as FuelType,
    plannedHandoverDate: model.plannedHandoverDate || null,
  };
}

@Component({
  selector: 'app-vehicle-form',
  imports: [FormField, FormRoot, RouterLink],
  templateUrl: './vehicle-form.html',
})
export class VehicleForm {
  private readonly vehicleApi = inject(VehicleApi);
  private readonly router = inject(Router);

  readonly id = input(undefined, { transform: optionalNumberAttribute });

  protected readonly isEdit = computed(() => this.id() !== undefined);
  protected readonly vehicle = this.vehicleApi.get(this.id);
  protected readonly fuelTypes = FUEL_TYPES;
  protected readonly fuelTypeLabels = FUEL_TYPE_LABELS;

  private readonly model = linkedSignal(() =>
    toFormModel(this.vehicle.hasValue() ? this.vehicle.value() : undefined),
  );

  protected readonly vehicleForm = form(
    this.model,
    (path) => {
      required(path.vin, { message: 'VIN is required' });
      required(path.make, { message: 'Make is required' });
      required(path.model, { message: 'Model is required' });
      required(path.productionYear, { message: 'Production year is required' });
      required(path.fuelType, { message: 'Fuel type is required' });
    },
    {
      submission: {
        action: async (vehicleForm) => {
          const request = toRequest(vehicleForm().value());
          const id = this.id();
          try {
            const saved = await firstValueFrom(
              id === undefined
                ? this.vehicleApi.create(request)
                : this.vehicleApi.update(id, request),
            );
            await this.router.navigate(['/vehicles', saved.id]);
            return undefined;
          } catch (error) {
            return problemDetailToFormErrors(error, vehicleForm);
          }
        },
      },
    },
  );

  protected loadError(error: unknown): string {
    return loadErrorMessage(error, 'Vehicle not found');
  }
}
<h1>{{ isEdit() ? 'Edit vehicle' : 'New vehicle' }}</h1>

@if (vehicle.isLoading()) {
  <p>Loading…</p>
} @else if (vehicle.error(); as error) {
  <p class="error" role="alert">{{ loadError(error) }}</p>
} @else if (!isEdit() || vehicle.hasValue()) {
  <form [formRoot]="vehicleForm">
    @for (error of vehicleForm().errors(); track error) {
      <p class="error" role="alert">{{ error.message }}</p>
    }

    <label>
      VIN
      <input type="text" [formField]="vehicleForm.vin" />
    </label>
    @if (vehicleForm.vin().touched()) {
      @for (error of vehicleForm.vin().errors(); track error) {
        <p class="error" role="alert">{{ error.message }}</p>
      }
    }

    <label>
      Make
      <input type="text" [formField]="vehicleForm.make" />
    </label>
    @if (vehicleForm.make().touched()) {
      @for (error of vehicleForm.make().errors(); track error) {
        <p class="error" role="alert">{{ error.message }}</p>
      }
    }

    <label>
      Model
      <input type="text" [formField]="vehicleForm.model" />
    </label>
    @if (vehicleForm.model().touched()) {
      @for (error of vehicleForm.model().errors(); track error) {
        <p class="error" role="alert">{{ error.message }}</p>
      }
    }

    <label>
      Production year
      <input type="number" [formField]="vehicleForm.productionYear" />
    </label>
    @if (vehicleForm.productionYear().touched()) {
      @for (error of vehicleForm.productionYear().errors(); track error) {
        <p class="error" role="alert">{{ error.message }}</p>
      }
    }

    <label>
      Fuel type
      <select [formField]="vehicleForm.fuelType">
        <option value="">Select fuel type</option>
        @for (fuelType of fuelTypes; track fuelType) {
          <option [value]="fuelType">{{ fuelTypeLabels[fuelType] }}</option>
